    @abstractmethod
    def _id(self) -> str:
        """
        Return a unique identifier for this rule.
        """

    @property
    def id(self) -> str:
        return self._id()

    @abstractmethod
    def _message(self) -> str:
        """
        Return a message that explains this rule.
        """

    @property
