                        if "static-files/lib/notebook-trace-renderer/index.html" in content_str:
                            violations.append(
                                Violation(
                                    rules.ForbiddenTraceUIInNotebook(),
                                    path,
                                    Location(0, 0),
                                    cell=index,
                                )
                            )
                            break
            if violations:  # Stop checking after finding the first violation
